production.storyboard:
[
  {
    "panelNumber": 1,
    "originalText": "Nhân sự do dự một chút: “Nhân viên mới… có ngân sách khích lệ.”",
    "description": "Composition: Medium shot. Lâm Vũ sitting at her desk, holding the phone receiver. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Female, 35, Outfit 1: White shirt, grey cardigan) holds the phone to her ear, her expression skeptical and waiting. Background shows blurred office environment.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 2,
    "originalText": "“Tiểu Chu được bao nhiêu?” Nhân sự không trả lời.",
    "description": "Composition: Close-up on Lâm Vũ's face. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 1) speaks into the phone with a demanding tone. She holds the phone tight, her eyes narrowing as she waits for an answer that doesn't come.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 3,
    "originalText": "Tôi hiểu rồi. Hiệu quả kinh doanh không tốt, nhân viên cũ được 0 đồng. Hiệu quả kinh doanh không tốt, nhân viên mới được 20.000.",
    "description": "Composition: Medium shot. Lâm Vũ slowly lowers the phone receiver onto the cradle. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 1) stares blankly into space, a look of bitter realization on her face. Visual metaphor: The numbers '0' and '20,000' floating in the air, contrasting each other.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 4,
    "originalText": "Đây chính là cái gọi là “cảm thông với công ty”. Chị Lý nói với tôi. Thưởng cuối năm của Tiểu Chu, 20.000.",
    "description": "Composition: Over-the-shoulder shot from Lâm Vũ looking at her phone screen (or Chị Lý nearby). \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 1) looks at a text message on her phone screen confirming '20,000'. Her face reflects deep hurt and validation of her suspicion.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 5,
    "originalText": "Buổi chiều, Vương tổng gọi tôi vào văn phòng.",
    "description": "Composition: Wide shot from inside the Manager's Office looking at the door. \nLighting: Afternoon sun streaming through blinds. \nAction: Lâm Vũ (Outfit 1) enters the office, standing tall and resolute. Vương Tổng (Outfit 2: Light grey suit) sits behind his desk.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 6,
    "originalText": "“Lâm Vũ à, chuyện thưởng cuối năm cô đừng để bụng.” Tôi nhìn ông ta.",
    "description": "Composition: Two-shot profile view. \nLighting: Afternoon sun creating a slightly tense atmosphere. \nAction: Vương Tổng (Outfit 2) leans forward on his desk with a fake sympathetic smile. Lâm Vũ (Outfit 1) stands opposite him, arms relaxed but posture rigid, staring at him coldly.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 7,
    "originalText": "“Năm nay công ty đúng là hiệu quả không tốt, cô là nhân viên lâu năm, phải làm gương mà cảm thông. Người mới ấy mà, phải khích lệ, không thì người ta bỏ đi mất.”",
    "description": "Composition: Medium shot of Vương Tổng. \nLighting: Afternoon sun. \nAction: Vương Tổng (Outfit 2) gestures with his hands, making excuses, his expression manipulative and insincere.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 8,
    "originalText": "“Vương tổng,” tôi lên tiếng, “tôi làm việc ở công ty mười năm rồi.”",
    "description": "Composition: Close-up on Lâm Vũ's face. \nLighting: Afternoon sun illuminates her face. \nAction: Lâm Vũ (Outfit 1) interrupts him, speaking calmly but firmly. Her gaze is steady.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 9,
    "originalText": "“Tôi biết,” Vương tổng gật đầu, “cho nên mới để cô làm gương. Nếu ngay cả cô cũng không thông cảm, người khác nghĩ sao?”",
    "description": "Composition: Over-the-shoulder shot from behind Lâm Vũ looking at Vương Tổng. \nLighting: Afternoon sun. \nAction: Vương Tổng (Outfit 2) nods dismissively, using his hands to emphasize his twisted logic about 'responsibility'.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 10,
    "originalText": "“Mười năm,” tôi nói tiếp, “lương của tôi từ 3.500 lên 8.000. Tiểu Chu vào ba tháng, lương 25.000.”",
    "description": "Composition: Medium shot of Lâm Vũ. \nLighting: Afternoon sun. \nAction: Lâm Vũ (Outfit 1) counts on her fingers or gestures to emphasize the numbers, her expression exposing the unfairness.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 11,
    "originalText": "Sắc mặt Vương tổng thay đổi. “Sao cô biết lương của cô ta?” “Chuyện đó quan trọng sao?”",
    "description": "Composition: Close-up on Vương Tổng's face. \nLighting: Afternoon sun casts shadows on his face. \nAction: Vương Tổng's (Outfit 2) fake smile vanishes, replaced by a frown and a look of being caught. He looks defensive.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 12,
    "originalText": "Vương tổng ho khan một tiếng: “Tình huống mỗi người mỗi khác, không thể so sánh như vậy được. Tiểu Chu là thạc sĩ 985, còn cô…”",
    "description": "Composition: Medium shot of Vương Tổng. \nLighting: Afternoon sun. \nAction: Vương Tổng (Outfit 2) clears his throat awkwardly, looking away slightly, trying to regain composure and make up excuses.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 13,
    "originalText": "“Tôi thì sao?”",
    "description": "Composition: Close-up on Lâm Vũ. \nLighting: Afternoon sun. \nAction: Lâm Vũ (Outfit 1) leans in slightly, her eyes challenging him to finish his sentence.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 14,
    "originalText": "“Cô là nhân viên lâu năm,” Vương tổng cười, “Người lâu năm mà, điều quan trọng nhất là ổn định.”",
    "description": "Composition: Medium shot of Vương Tổng. \nLighting: Afternoon sun. \nAction: Vương Tổng (Outfit 2) forces a smile again, leaning back in his chair, spreading his hands in a 'you know how it is' gesture.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 15,
    "originalText": "Ổn định. Ý là, tôi không đi được, nên không cần tăng lương.",
    "description": "Composition: Extreme close-up on Lâm Vũ's eyes. \nLighting: Reflection of the office in her glasses. \nAction: Lâm Vũ (Outfit 1) stares intensely, realizing the cruel truth. Her expression hardens.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 16,
    "originalText": "“Vương tổng,” tôi đứng dậy, “tôi muốn nộp đơn nghỉ việc.”",
    "description": "Composition: Medium shot. Lâm Vũ stands up straight from a chair (or straightens her posture if already standing). \nLighting: Afternoon sun. \nAction: Lâm Vũ (Outfit 1) stands tall and resolute, looking down at Vương Tổng seated.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 17,
    "originalText": "Không khí im bặt trong ba giây. Vương tổng sững người. “Cô nói gì?”",
    "description": "Composition: Close-up on Vương Tổng. \nLighting: Afternoon sun. \nAction: Vương Tổng (Outfit 2) freezes, his mouth slightly open, eyes wide in shock.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 18,
    "originalText": "“Tôi muốn nghỉ việc.”",
    "description": "Composition: Close-up on Lâm Vũ. \nLighting: Afternoon sun. \nAction: Lâm Vũ (Outfit 1) repeats her words calmly and clearly, maintaining eye contact.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 19,
    "originalText": "Vương tổng nhìn tôi, ánh mắt phức tạp. Rồi ông ta cười. “Lâm Vũ, cô đừng đùa nữa.” “Tôi không đùa.”",
    "description": "Composition: Two-shot. \nLighting: Afternoon sun. \nAction: Vương Tổng (Outfit 2) lets out a nervous, fake laugh, waving his hand dismissively. Lâm Vũ (Outfit 1) remains stone-faced and serious.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 20,
    "originalText": "Vương tổng đứng dậy, bước đến trước mặt tôi. “Cô 35 tuổi rồi, ra ngoài tìm được việc gì? Đừng hành động bốc đồng.”",
    "description": "Composition: Low angle shot looking up at Vương Tổng standing close to Lâm Vũ. \nLighting: Vương Tổng casts a shadow over Lâm Vũ. \nAction: Vương Tổng (Outfit 2) stands up and moves close to Lâm Vũ, looking down at her intimidatingly, pointing a finger or gesturing aggressively.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 21,
    "originalText": "Tôi nhìn ông ta. “Vương tổng, ông vừa nói, nhân viên lâu năm thì ổn định là quan trọng nhất.” “Đúng thế.”",
    "description": "Composition: Close-up on Lâm Vũ looking up at Vương Tổng. \nLighting: Shadow on her face, but eyes are bright. \nAction: Lâm Vũ (Outfit 1) meets his gaze fearlessly, speaking with logical precision.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 22,
    "originalText": "“Vậy ông đã từng nghĩ chưa,” tôi nói, “nếu tôi không còn ổn định nữa, sẽ ra sao?”",
    "description": "Composition: Extreme close-up on Lâm Vũ's face, specifically her mouth and eyes. \nLighting: Dramatic lighting. \nAction: Lâm Vũ (Outfit 1) smiles a cold, mysterious smile, delivering her threat.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 23,
    "originalText": "Vương tổng sững lại. “Ý cô là gì?”",
    "description": "Composition: Medium shot of Vương Tổng. \nLighting: Afternoon sun. \nAction: Vương Tổng (Outfit 2) steps back slightly, his intimidating posture faltering. He looks confused and uneasy.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 24,
    "originalText": "Tôi không trả lời. Tôi xoay người rời khỏi văn phòng. Sau lưng vang lên giọng nói của Vương tổng. “Lâm Vũ! Quay lại đây!” Tôi không quay đầu.",
    "description": "Composition: View from the office doorway looking out. Lâm Vũ walks away down the corridor. Vương Tổng stands in the doorway background. \nLighting: Bright corridor vs shadowed office. \nAction: Lâm Vũ (Outfit 1) walks away decisively, back to camera. Vương Tổng (Outfit 2) stands in the background shouting, hand reaching out futilely.",
    "timeOfDay": "Afternoon"
  },
  {
    "panelNumber": 25,
    "originalText": "Ngày hôm sau, tôi chính thức nộp đơn xin nghỉ việc. 30 ngày — đây là thời hạn bàn giao theo quy định pháp luật.",
    "description": "Composition: Close-up of a hand placing a resignation letter on a desk. \nLighting: Morning office light. \nAction: Lâm Vũ's hand (Female, 35, Outfit 1: White shirt, grey cardigan) places a white envelope labeled 'Resignation Letter' firmly on a wooden desk.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 26,
    "originalText": "Sau khi nhận được đơn, Vương tổng gọi tôi vào văn phòng. “Lâm Vũ, cô đã suy nghĩ kỹ chưa?” “Rồi.”",
    "description": "Composition: Medium shot in Manager's Office. \nLighting: Morning office light. \nAction: Vương Tổng (Outfit 2) sits at his desk holding the letter, looking serious. Lâm Vũ (Outfit 1) stands in front of the desk, calm and composed.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 27,
    "originalText": "Vương tổng cau mày. “Là vì chuyện thưởng cuối năm sao? Được, tôi có thể bù cho cô. 5000, thế nào?”",
    "description": "Composition: Close-up on Vương Tổng. \nLighting: Morning office light. \nAction: Vương Tổng (Outfit 2) frowns, leaning forward and making a bargaining gesture with his hand.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 28,
    "originalText": "Tiểu Chu được 20.000, ông ta bù cho tôi 5000. “Vương tổng, không phải vấn đề tiền bạc.”",
    "description": "Composition: Medium shot of Lâm Vũ. \nLighting: Morning office light. \nAction: Lâm Vũ (Outfit 1) shakes her head slightly, a look of quiet disdain on her face.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 29,
    "originalText": "“Vậy là vấn đề gì?” “Tôi mệt rồi.”",
    "description": "Composition: Close-up on Lâm Vũ. \nLighting: Morning office light. \nAction: Lâm Vũ (Outfit 1) sighs softly, her shoulders dropping slightly in a gesture of fatigue and finality.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 30,
    "originalText": "Vương tổng im lặng một lúc. “Vậy cô muốn bao nhiêu? 10.000?”",
    "description": "Composition: Medium shot of Vương Tổng. \nLighting: Morning office light. \nAction: Vương Tổng (Outfit 2) looks calculating, raising his eyebrows as he increases the offer.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 31,
    "originalText": "Tôi cười. “Vương tổng, tôi đã nói rồi, không phải vấn đề tiền.”",
    "description": "Composition: Medium shot of Lâm Vũ. \nLighting: Morning office light. \nAction: Lâm Vũ (Outfit 1) smiles a polite but firm smile, shaking her head again.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 32,
    "originalText": "“Vậy rốt cuộc cô muốn thế nào?” Vương tổng cao giọng, “Cô nói đi!”",
    "description": "Composition: Low angle shot of Vương Tổng. \nLighting: Morning office light. \nAction: Vương Tổng (Outfit 2) stands up abruptly or slams a hand on the desk, looking angry and frustrated.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 33,
    "originalText": "Tôi nhìn ông ta. “Tôi muốn đi.”",
    "description": "Composition: Close-up on Lâm Vũ. \nLighting: Morning office light. \nAction: Lâm Vũ (Outfit 1) looks straight ahead with unwavering determination.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 34,
    "originalText": "Vương tổng nhìn chằm chằm tôi, trong ánh mắt có tức giận, có bối rối, còn có một chút… hoảng hốt?",
    "description": "Composition: Extreme close-up on Vương Tổng's eyes. \nLighting: Morning office light. \nAction: Vương Tổng's (Outfit 2) eyes widen slightly, showing a mix of anger and hidden panic.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 35,
    "originalText": "“Được,” ông ta ngồi lại xuống ghế, “Cô đi đi. 30 ngày bàn giao, bàn giao cho tử tế.”",
    "description": "Composition: Medium shot. Vương Tổng sits back down heavily. \nLighting: Morning office light. \nAction: Vương Tổng (Outfit 2) collapses back into his chair, waving his hand dismissively, looking defeated and sullen.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 36,
    "originalText": "“Vâng.” Tôi quay người định rời đi.",
    "description": "Composition: View from behind Lâm Vũ. \nLighting: Morning office light. \nAction: Lâm Vũ (Outfit 1) turns around to leave the office.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 37,
    "originalText": "“Khoan đã,” Vương tổng gọi tôi lại, “Cô định đi đâu?” Tôi quay đầu nhìn ông ta. “Vương tổng, chuyện này quan trọng sao?”",
    "description": "Composition: Over-the-shoulder shot from behind Vương Tổng. \nLighting: Morning office light. \nAction: Lâm Vũ (Outfit 1) pauses at the door, turning her head back slightly with a mysterious smile.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 38,
    "originalText": "Vương tổng không nói gì. Tôi bước ra khỏi văn phòng. Trở lại chỗ ngồi, bắt đầu thu dọn đồ đạc.",
    "description": "Composition: Medium shot at Lâm Vũ's desk in the General Office Area. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 1) is placing personal items (a mug, a plant, a photo frame) into a cardboard box.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 39,
    "originalText": "Tiểu Chu đi tới. “Chị Lâm, em nghe nói chị muốn nghỉ việc?” “Ừ.”",
    "description": "Composition: Medium shot. Tiểu Chu approaches Lâm Vũ's desk. \nLighting: Bright office lighting. \nAction: Tiểu Chu (Outfit 2: Pastel pink dress) stands by the desk with a feigned look of concern/curiosity. Lâm Vũ (Outfit 1) continues packing, barely looking up.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 40,
    "originalText": "“Tại sao vậy?” Tôi nhìn cô ta. “Tiểu Chu, cô nghĩ là vì sao?”",
    "description": "Composition: Two-shot. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 1) stops packing and looks directly at Tiểu Chu with a piercing, sarcastic gaze. Tiểu Chu (Outfit 2) looks slightly taken aback.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 41,
    "originalText": "Tiểu Chu khựng lại một chút, rồi cười. “Chị Lâm, có phải vì chuyện em làm quản lý không? Chị yên tâm, em rất tôn trọng chị, sau này có việc gì mình có thể bàn bạc.”",
    "description": "Composition: Close-up on Tiểu Chu. \nLighting: Bright office lighting. \nAction: Tiểu Chu (Outfit 2) puts on a condescending, 'magnanimous' smile, placing a hand on her chest in a gesture of sincerity.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 42,
    "originalText": "Tôi không nói gì. “Hơn nữa,” Tiểu Chu hạ giọng, “Vương tổng bảo em khuyên chị, nói nếu chị ở lại thì có thể tăng lương.”",
    "description": "Composition: Two-shot. Tiểu Chu leans in closer to Lâm Vũ. \nLighting: Bright office lighting. \nAction: Tiểu Chu (Outfit 2) leans in to whisper conspiratorially. Lâm Vũ (Outfit 1) stands still, listening impassively.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 43,
    "originalText": "“Tăng bao nhiêu?” “10.000.”",
    "description": "Composition: Close-up on Tiểu Chu's face. \nLighting: Bright office lighting. \nAction: Tiểu Chu (Outfit 2) holds up one finger or whispers the number with a look that suggests she thinks this is a huge favor.",
    "timeOfDay": "Day (Next day)"
  }
]

